// Manual p.189 names these controls; ranges and response-step pacing are reconstruction tuning.
export const TORNADO_DIRECTIONS={automatic:'Toward city center',north:'North',northeast:'Northeast',east:'East',southeast:'Southeast',south:'South',southwest:'Southwest',west:'West',northwest:'Northwest'};
export const TORNADO_SPEEDS={slow:'Slow · one tile every two response steps',normal:'Normal · one tile per response step',fast:'Fast · two tiles per response step'};
export const defaultTornadoSettings=()=>({direction:'automatic',intensity:50,distance:24,speed:'normal',warning:true});
export function validateTornadoSettings(v){if(v===undefined)return defaultTornadoSettings();if(!v||!Object.hasOwn(TORNADO_DIRECTIONS,v.direction)||!Number.isInteger(v.intensity)||v.intensity<1||v.intensity>100||!Number.isInteger(v.distance)||v.distance<1||v.distance>256||!Object.hasOwn(TORNADO_SPEEDS,v.speed)||typeof v.warning!=='boolean')throw Error('Choose a tornado direction, intensity 1–100, distance 1–256, speed and warning setting.');return{direction:v.direction,intensity:v.intensity,distance:v.distance,speed:v.speed,warning:v.warning};}
export function tornadoVector(direction,x,y,size){if(direction==='automatic'){const horizontal=Math.abs(x-size/2)>=Math.abs(y-size/2);return[horizontal?(x<size/2?1:-1):0,horizontal?0:(y<size/2?1:-1)];}return{north:[0,-1],northeast:[1,-1],east:[1,0],southeast:[1,1],south:[0,1],southwest:[-1,1],west:[-1,0],northwest:[-1,-1]}[direction];}
export const tornadoSettingsLabel=v=>`${TORNADO_DIRECTIONS[v.direction]} · Intensity ${v.intensity} · ${v.distance} tiles · ${v.speed} · Early warning ${v.warning?'on':'off'}`;
export function validateTornadoMotion(t,version){if(!t)throw Error('Invalid tornado state.');if(version<116)return{intensity:50,distance:24,speed:'normal',phase:0};const v=validateTornadoSettings({direction:'automatic',intensity:t.intensity,distance:t.distance,speed:t.speed,warning:true});if(!Number.isInteger(t.phase)||t.phase<0||t.phase>(v.speed==='slow'?1:0)||t.phase&&(!t.age||t.warningSteps))throw Error('Invalid tornado movement phase.');return{intensity:v.intensity,distance:v.distance,speed:v.speed,phase:t.phase};}
